-- ================================================================
-- Migration 022 — Importar atas históricas (34ª RO a 37ª RO)
-- v3: limpeza de quebras de linha artificiais do PDF, ordinais corrigidos.
-- Idempotente: re-executar atualiza o conteúdo.
-- ================================================================
DO $$
DECLARE v_id uuid; v_ata uuid;
BEGIN

  -- 34ª RO (2024-08-31)
  INSERT INTO reunioes (numero, data_inicio, data_fim, tipo, status)
  VALUES ('34ª RO', '2024-08-31', '2024-08-31', 'ordinaria', 'realizada')
  ON CONFLICT (numero) DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NULL THEN SELECT id INTO v_id FROM reunioes WHERE numero = '34ª RO'; END IF;

  SELECT id INTO v_ata FROM atas WHERE reuniao_id = v_id;
  IF v_ata IS NULL THEN
    INSERT INTO atas (reuniao_id, status, conteudo) VALUES (v_id, 'publicada', '{"verificacao_poderes": "ATA DO ATO DE VERIFICAÇÃO DE PODERES DA 34ª REUNIÃO ORDINÁRIA DO PRESBITÉRIO LESTE DE SÃO PAULO - PSSP. Às 9h08m, do dia trinta e um de agosto de dois mil e vinte e quatro, (31/08/2024), na Igreja Presbiteriana em Vila Lais, sito Dr. Virgílio Machado, no528, CEP 03733-180, Vila Lais, São Paulo - Capital, reúne-se, previamente convocado, o Presbitério Leste de São Paulo. COMPOSIÇÃO DA MESA : Reverendo Rev. Amauri Costa de Oliveira, Presidente, Rev. Carlos Alberto Henrique, Vice-presidente, Rev. Daniel Fogaça, 1º Secretário, Rev. César Veríssimo Marinho dos Reis, 2º Secretário, Presb. Valdir Soranso, Tesoureiro e Presb. Anízio Alves Borges, Secretário Executivo. É feita a chamada pelo Sr. Secretário Executivo, registra-se a presença dos pastores que apresentam suas carteiras de Ministro, Rev. Amauri Costa de Oliveira, Rev. Atshishi Miyajima, Rev. Carlos Eduardo Correa Lima, Rev.Carlos Roberto Spiaze, Rev. César Veríssimo Marinho dos Reis, Rev. Cornélio Caldeira de Castro, Rev. Daniel Fogaça, Rev. Felipe Gomes Checon Pereira, Rev. Gustavo Alex Faria Custódio, Rev. Israel Scalioni, Rev. Laércio Máximo Rodrigues, Rev. Jairo Isac Rodrigues, Rev. Maycon Rodrigues, Rev. Rogério de Castro Chaves, Rev. Vagner de jesus Queirós Rev. Wellington Aparecido Costa Baldes, registrando que todos os presentes assinaram o livro de presença do Concílio. Ausências dos Ministros: Rev. Carlos Alberto Henrique, Rev. Jean Francesco Afonso Lima Gomes, Rev. Jessé Silveira Fogaça, encontra-se trabalhando em campo missionário no Timor Leste, na Ásia, Rev. Juliano Caetano Socio, Rev. Michael Fassehbes Valim Cruz. Registra-se a presença das seguintes Igrejas, por meio de seus respectivos representantes: I. P. DE VILA LAIS, Presb. Cleber Rodrigues, I. P. DE VILA BUENOS AIRES, Presb. Idenal Nichimura, I. P. Jardim Popular , Presb. Mauro Silva, I. P. da PENHA , Presb. Anízio Alves Borges, , I. P. VILA ESPERANÇA , Presb. Eduardo Mendes Machado. Ausente o Representante da I. P. DO JARDIM CASTELO. Havendo quórum, as 9h16min, o presidente, Rev. Amaurideclara instalada a 34ª Reunião Ordinária do Presbitério Leste de São Paulo. Às 9h16min, encerra-se a sessão de veriﬁcação de poderes, com oração pelo Rev. Vagner. E para constar eu, Reverendo César Veríssimo Marinho dos Reis, 2º Secretario, a tudo presente, digito, dato, e assino a presente ata, a qual será transcrita pelo Secretário Executivo, Presb. Anízio Alves Borges, em livro próprio. São Paulo, 30/08/2024.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.", "sessao_preparatoria": "ATA DA SESSÃO PREPARATÓRIA DA 34.aREUNIÃO ORDINÁRIA DO PRESBITÉRIO LESTE DE SÃO PAULO - PSSP . Aos trinta e um dias do mês de agosto de 2024, às 9h17m, passa-se ao exercício devocional, O Rev. Cornélio dirige a Igreja nos louvores com um \" poupurri \"de cânticos e em seguida ora em louvor a Deus. O Rev. Maycon lê o texto bíblico em Lucas 24: 13 a 25 e ministra sob o tema: Um regate ao Ministério Pastoral e argumenta 1) O que nos Impede de reconhecer o senhor no Caminho Ministerial; 2) Quando perdemos a Esperança na Mensagem que pregamos; 3) Sentar-se à Mesa com Jesus é a Nossa Salvação, a igreja é separada em duplas para que se ore um pelo outro. As 9h46min, encerra-se o Exercício Espiritual com oração pelo Rev. Maycon. E para constar eu, Reverendo César Veríssimo Marinho dos Reis, 2.oSecretário, a tudo presente, digito, dato e assino a presente Ata, a qual será transcrita pelo Secretário Executivo, Presbítero Anízio Alves Borges. São Paulo, 31/08/2024", "sessoes_regulares": ["ATA DA SESSÃO REGULAR ÙNICA DA 34.aREUNIÃO ORDINÁRIA DO PRESBITÉRIO LESTE DE SÃO PAULO . Aos trinta e um dias do mês de agosto de 2024, às 9h47min, sob a presidência do Reverendo Amauri, e membros da mesa, Rev. Amauri Costa de Oliveira, presidente, Rev. Amauri Costa de Oliveira, Vice-presidente; Rev. Daniel Fogaça, 1osecretário; Rev. César Veríssimo Marinho dos Reis, 2osecre tário; Presb. Valdir Soranso, Tesoureiro e Presb. Anízio Alves Borges, Secretário Executivo e membros do Concílio supracitados. O Sr. Presidente chama o ver. Wellington para compor a Mesa substituindo o Rev. Carlos Henrique que se encontra adoentado. Dá-se Entrada aos Documentos: Doc. 01 , Convocação. Toma-se conhecimento e arquiva-se; Doc. 02 , Justiﬁcativa de Ausência do Rev. Adriano Pedrosa Ferreira, toma-se conhecimento e arquiva-se. Doc 03 , Credencial do Representante da I. P . Jd. Popular, Presb. Mauro Silva e Suplente o Presb. Valdeck Moreira da Silva, toma-se conhecimento e arquiva-se. Doc. 04, Carta de Cessão e Apoio Financeiro da APMT acerca do Miss. Rev. Jairo Isac Rodrigues, aprova-se. Doc. 05 , Carta de Cessão e Apoio Financeiro da APMT acerca do Miss. Rev. Jesse Silveira Fogaça, aprova-se. Doc. 06 , Carta sobre Campo Ministerial para o Exercício do ano de 2025 da I.P . Jd. Popular solicitando a permanência do Rev. Laércio Máximo Rodrigues, aprova-se. Doc. 07, Carta da APMT solicitando, reconhecimento da Igreja Curda como Igreja Presbiteriana (Igreja Presbiteriana Curda) e vincular o Rev. Amir Mohamed da região do Curdistão Iraquiano, aprova-se nos seus termos. Doc. 08 , Carta da I.P . Vl. Esperança quanto ao Campo pastoral solicitando a designação do Rev. Israel Scalioni para 2025, aprova-se. Doc. 09 , Carta da I.P . Vl. Lais quanto ao Campo Pastoral solicitando a permanência do Rev. Maycon em seu campo, aprova-se. Doc. 10 , Carta da I.P . Vl. Buenos Aires solicitando a designação do Rev. Vagner como pastor auxiliar e colocando o Lic. Ayrton da Silva Moreira Gomes à disposição do Presbitério uma vez que o mesmo completa os 3 anos de sua Licenciatura conforme preceitua o art. 124 parágrafo 3º, aprova-se nos seus termos. Doc. 11 , Carta da I.P . do Jd. Castelo solicitando a nomeação do Rev. Daniel Fogaça para o ano de 2025, aprova-se. Doc. 12 , Carta da I.P . Penha solicitando as nomeações dos seguintes pastores auxiliares para o ano de 2025: Rev. Juliano Caetano sócio, Carlos Alberto Henrique, Rev. Wellington Aparecido Costa Baldes, Rev. Cornélio Caldeira de Castro, Rev. Jean Francesco Afonso Lima Gomes, Rev. Carlos Eduardo Correa Lima, Rev. Filipe Gomes Checon Pereira, Rev. Michael Fassheber Vallim da Cruz, Rev. Rogério de Castro Chaves, Rev. Atsushi Miyajima, e Rev. Adriano Pedrosa Ferreira, aprova-se. Doc. 13 , Carta da I.P . Penha solicitando transferência e recebimento do Rev. Fábio Luiz de Carvalho como pastor auxiliar da Igreja para 2025, aprova-se nos seus termos. Doc. 14 , Carta do Secretário Presbiterial do Trabalho com a Juventude do PSSP solicitando verba para realização de workshop e treinamento para jovens líderes da região. Doc. 15 , Relatório da comissão de Exame de Monograﬁa do candidato Ricardo Riul: \" A comissão resolve: aprovar o relatório, recomendando que faça as correções apontadas no relatório, e encaminhá-lo a comissão até dia 31/out/24 e feito as correções solicitadas, propõe-se que o candidato seja sabatinado na reunião do PSSP EM dezembro/24, dando-se os passos constitucionais \", aprova-se. Doc. 16 , Carta de Cessão e Apoio Financeiro da APMT acerca do Miss. Rev. Gustavo Alex Faria Custódio, aprova-se. Marca-se a próxima reunião do PSSP para o dia 14/12/2024 na Cong. Anália. Encerra-se a reunião com uma oração pelo Rev. Gustavo às 11h45min. Eu, Rev. César Veríssimo Marinho dos Reis, 2.oSecretário, a tudo presente, digito, dato e assino a presente ata, a qual será transcrita pelo Secretário Executivo, Presb. Anízio Alves Borges. São Paulo, 31 de agosto de 2024. - - - - - - - - - - - - - - - - - - - - - - -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------51"], "observacoes": ""}'::jsonb);
  ELSE
    UPDATE atas SET conteudo = '{"verificacao_poderes": "ATA DO ATO DE VERIFICAÇÃO DE PODERES DA 34ª REUNIÃO ORDINÁRIA DO PRESBITÉRIO LESTE DE SÃO PAULO - PSSP. Às 9h08m, do dia trinta e um de agosto de dois mil e vinte e quatro, (31/08/2024), na Igreja Presbiteriana em Vila Lais, sito Dr. Virgílio Machado, no528, CEP 03733-180, Vila Lais, São Paulo - Capital, reúne-se, previamente convocado, o Presbitério Leste de São Paulo. COMPOSIÇÃO DA MESA : Reverendo Rev. Amauri Costa de Oliveira, Presidente, Rev. Carlos Alberto Henrique, Vice-presidente, Rev. Daniel Fogaça, 1º Secretário, Rev. César Veríssimo Marinho dos Reis, 2º Secretário, Presb. Valdir Soranso, Tesoureiro e Presb. Anízio Alves Borges, Secretário Executivo. É feita a chamada pelo Sr. Secretário Executivo, registra-se a presença dos pastores que apresentam suas carteiras de Ministro, Rev. Amauri Costa de Oliveira, Rev. Atshishi Miyajima, Rev. Carlos Eduardo Correa Lima, Rev.Carlos Roberto Spiaze, Rev. César Veríssimo Marinho dos Reis, Rev. Cornélio Caldeira de Castro, Rev. Daniel Fogaça, Rev. Felipe Gomes Checon Pereira, Rev. Gustavo Alex Faria Custódio, Rev. Israel Scalioni, Rev. Laércio Máximo Rodrigues, Rev. Jairo Isac Rodrigues, Rev. Maycon Rodrigues, Rev. Rogério de Castro Chaves, Rev. Vagner de jesus Queirós Rev. Wellington Aparecido Costa Baldes, registrando que todos os presentes assinaram o livro de presença do Concílio. Ausências dos Ministros: Rev. Carlos Alberto Henrique, Rev. Jean Francesco Afonso Lima Gomes, Rev. Jessé Silveira Fogaça, encontra-se trabalhando em campo missionário no Timor Leste, na Ásia, Rev. Juliano Caetano Socio, Rev. Michael Fassehbes Valim Cruz. Registra-se a presença das seguintes Igrejas, por meio de seus respectivos representantes: I. P. DE VILA LAIS, Presb. Cleber Rodrigues, I. P. DE VILA BUENOS AIRES, Presb. Idenal Nichimura, I. P. Jardim Popular , Presb. Mauro Silva, I. P. da PENHA , Presb. Anízio Alves Borges, , I. P. VILA ESPERANÇA , Presb. Eduardo Mendes Machado. Ausente o Representante da I. P. DO JARDIM CASTELO. Havendo quórum, as 9h16min, o presidente, Rev. Amaurideclara instalada a 34ª Reunião Ordinária do Presbitério Leste de São Paulo. Às 9h16min, encerra-se a sessão de veriﬁcação de poderes, com oração pelo Rev. Vagner. E para constar eu, Reverendo César Veríssimo Marinho dos Reis, 2º Secretario, a tudo presente, digito, dato, e assino a presente ata, a qual será transcrita pelo Secretário Executivo, Presb. Anízio Alves Borges, em livro próprio. São Paulo, 30/08/2024.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.", "sessao_preparatoria": "ATA DA SESSÃO PREPARATÓRIA DA 34.aREUNIÃO ORDINÁRIA DO PRESBITÉRIO LESTE DE SÃO PAULO - PSSP . Aos trinta e um dias do mês de agosto de 2024, às 9h17m, passa-se ao exercício devocional, O Rev. Cornélio dirige a Igreja nos louvores com um \" poupurri \"de cânticos e em seguida ora em louvor a Deus. O Rev. Maycon lê o texto bíblico em Lucas 24: 13 a 25 e ministra sob o tema: Um regate ao Ministério Pastoral e argumenta 1) O que nos Impede de reconhecer o senhor no Caminho Ministerial; 2) Quando perdemos a Esperança na Mensagem que pregamos; 3) Sentar-se à Mesa com Jesus é a Nossa Salvação, a igreja é separada em duplas para que se ore um pelo outro. As 9h46min, encerra-se o Exercício Espiritual com oração pelo Rev. Maycon. E para constar eu, Reverendo César Veríssimo Marinho dos Reis, 2.oSecretário, a tudo presente, digito, dato e assino a presente Ata, a qual será transcrita pelo Secretário Executivo, Presbítero Anízio Alves Borges. São Paulo, 31/08/2024", "sessoes_regulares": ["ATA DA SESSÃO REGULAR ÙNICA DA 34.aREUNIÃO ORDINÁRIA DO PRESBITÉRIO LESTE DE SÃO PAULO . Aos trinta e um dias do mês de agosto de 2024, às 9h47min, sob a presidência do Reverendo Amauri, e membros da mesa, Rev. Amauri Costa de Oliveira, presidente, Rev. Amauri Costa de Oliveira, Vice-presidente; Rev. Daniel Fogaça, 1osecretário; Rev. César Veríssimo Marinho dos Reis, 2osecre tário; Presb. Valdir Soranso, Tesoureiro e Presb. Anízio Alves Borges, Secretário Executivo e membros do Concílio supracitados. O Sr. Presidente chama o ver. Wellington para compor a Mesa substituindo o Rev. Carlos Henrique que se encontra adoentado. Dá-se Entrada aos Documentos: Doc. 01 , Convocação. Toma-se conhecimento e arquiva-se; Doc. 02 , Justiﬁcativa de Ausência do Rev. Adriano Pedrosa Ferreira, toma-se conhecimento e arquiva-se. Doc 03 , Credencial do Representante da I. P . Jd. Popular, Presb. Mauro Silva e Suplente o Presb. Valdeck Moreira da Silva, toma-se conhecimento e arquiva-se. Doc. 04, Carta de Cessão e Apoio Financeiro da APMT acerca do Miss. Rev. Jairo Isac Rodrigues, aprova-se. Doc. 05 , Carta de Cessão e Apoio Financeiro da APMT acerca do Miss. Rev. Jesse Silveira Fogaça, aprova-se. Doc. 06 , Carta sobre Campo Ministerial para o Exercício do ano de 2025 da I.P . Jd. Popular solicitando a permanência do Rev. Laércio Máximo Rodrigues, aprova-se. Doc. 07, Carta da APMT solicitando, reconhecimento da Igreja Curda como Igreja Presbiteriana (Igreja Presbiteriana Curda) e vincular o Rev. Amir Mohamed da região do Curdistão Iraquiano, aprova-se nos seus termos. Doc. 08 , Carta da I.P . Vl. Esperança quanto ao Campo pastoral solicitando a designação do Rev. Israel Scalioni para 2025, aprova-se. Doc. 09 , Carta da I.P . Vl. Lais quanto ao Campo Pastoral solicitando a permanência do Rev. Maycon em seu campo, aprova-se. Doc. 10 , Carta da I.P . Vl. Buenos Aires solicitando a designação do Rev. Vagner como pastor auxiliar e colocando o Lic. Ayrton da Silva Moreira Gomes à disposição do Presbitério uma vez que o mesmo completa os 3 anos de sua Licenciatura conforme preceitua o art. 124 parágrafo 3º, aprova-se nos seus termos. Doc. 11 , Carta da I.P . do Jd. Castelo solicitando a nomeação do Rev. Daniel Fogaça para o ano de 2025, aprova-se. Doc. 12 , Carta da I.P . Penha solicitando as nomeações dos seguintes pastores auxiliares para o ano de 2025: Rev. Juliano Caetano sócio, Carlos Alberto Henrique, Rev. Wellington Aparecido Costa Baldes, Rev. Cornélio Caldeira de Castro, Rev. Jean Francesco Afonso Lima Gomes, Rev. Carlos Eduardo Correa Lima, Rev. Filipe Gomes Checon Pereira, Rev. Michael Fassheber Vallim da Cruz, Rev. Rogério de Castro Chaves, Rev. Atsushi Miyajima, e Rev. Adriano Pedrosa Ferreira, aprova-se. Doc. 13 , Carta da I.P . Penha solicitando transferência e recebimento do Rev. Fábio Luiz de Carvalho como pastor auxiliar da Igreja para 2025, aprova-se nos seus termos. Doc. 14 , Carta do Secretário Presbiterial do Trabalho com a Juventude do PSSP solicitando verba para realização de workshop e treinamento para jovens líderes da região. Doc. 15 , Relatório da comissão de Exame de Monograﬁa do candidato Ricardo Riul: \" A comissão resolve: aprovar o relatório, recomendando que faça as correções apontadas no relatório, e encaminhá-lo a comissão até dia 31/out/24 e feito as correções solicitadas, propõe-se que o candidato seja sabatinado na reunião do PSSP EM dezembro/24, dando-se os passos constitucionais \", aprova-se. Doc. 16 , Carta de Cessão e Apoio Financeiro da APMT acerca do Miss. Rev. Gustavo Alex Faria Custódio, aprova-se. Marca-se a próxima reunião do PSSP para o dia 14/12/2024 na Cong. Anália. Encerra-se a reunião com uma oração pelo Rev. Gustavo às 11h45min. Eu, Rev. César Veríssimo Marinho dos Reis, 2.oSecretário, a tudo presente, digito, dato e assino a presente ata, a qual será transcrita pelo Secretário Executivo, Presb. Anízio Alves Borges. São Paulo, 31 de agosto de 2024. - - - - - - - - - - - - - - - - - - - - - - -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------51"], "observacoes": ""}'::jsonb, status = 'publicada' WHERE id = v_ata;
  END IF;
  RAISE NOTICE '34ª RO importada';


  -- 35ª RO (2024-12-14)
  INSERT INTO reunioes (numero, data_inicio, data_fim, tipo, status)
  VALUES ('35ª RO', '2024-12-14', '2024-12-14', 'ordinaria', 'realizada')
  ON CONFLICT (numero) DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NULL THEN SELECT id INTO v_id FROM reunioes WHERE numero = '35ª RO'; END IF;

  SELECT id INTO v_ata FROM atas WHERE reuniao_id = v_id;
  IF v_ata IS NULL THEN
    INSERT INTO atas (reuniao_id, status, conteudo) VALUES (v_id, 'publicada', '{"verificacao_poderes": "VERIFICAÇÃO DE PODERES DA 35ª REUNIÃO ORDINÁRIA DO PRESBITÉRIO LESTE DE SÃO PAULO - PSSP. Às 9h, do dia catorze do mês de dezembro do ano dois mil e vinte quatro, (14/12/2024), na Congregação Presbiteriana de Anália Franco, sito na Rua Acuruí, 327, Vila Formosa, São Paulo, Capital, CEP 03355-000, reúne-se, previamente convocado, o Presbitério Leste de São Paulo PSSP . COMPOSIÇÃO DA MESA : Reverendo Amauri Costa de Oliveira, Presidente, Reverendo Carlos Alberto Henrique, Vice-Presidente, Presbítero Anízio Alves Borges, Secretário Executivo, Reverendo Daniel Fogaça, 1º Secretário, Reverendo César Veríssimo Marinho dos Reis, 2osecretário, e Presbítero Valdir Soranso, Tesoureiro. Feita a chamada pelo Secretário Executivo, registram-se a presença dos Pastores que apresentam suas Carteiras de Ministro, Rev. Adriano Pedrosa Ferreira, Rev. Amauri Costa de Oliveira, Rev. Atsushi Miyajima, Rev. Carlos Alberto Henrique, Rev. Carlos Eduardo Correa Lima, Rev. Cesar Veríssimo Marinho dos Reis, Rev. Daniel Fogaça, Rev. Filipe Gomes Checon Pereira, Rev. Gustavo Alex Faria Custódio, Rev. Israel Scalioni, Rev. Laércio Máximo Rodrigues, Rev. Jairo Isac Rodrigues, Rev. Michael Fassheber Valim Cruz, Rev. Maycon Rodrigues, Rev. Rogério de Castro Chaves, Rev. Vagner de Jesus Queiros, e Rev. Wellington Aparecido Costa Baldez, registrando que todos os presentes assinaram o Livro de presença do Concílio. Ausências dos Ministros: Rev. Jean Francesco Afonso Lima Gomes, Rev. Cornélio Caldeira de Castro, Rev. Carlos Roberto Spiaze, Rev. Juliano Caetano Socio, Rev. Jessé Silveira Fogaça, reiterando que este último, encontra-se em seu campo missionário no Timor Leste, na Ásia, todas as ausências são justiﬁcadas. Registram-se a presença das seguintes Igrejas, por meio de seus respectivos representantes : IP da PENHA , Presb. Anízio Alves Borges; IP da VILA ESPERANÇA , Presb. Eduardo Mendes Machado, IP de VILA LAIS, Presb. Cleber Rodrigues do Nascimento, e IP DE VILA BUENOS AIRES , Presb. Idenal Nichimura. Ausentes os Representantes das Igrejas :IP do JARDIM CASTELO. eIP do JARDIM POPULAR. Havendo quórum, as 9h10m, o Presidente, Rev. Amauri Costa de Oliveira declara instalada a 35ª Reunião Ordinária do PSSP , Presbitério Leste de São Paulo. Às 9h11min, encerra-se a sessão de\n\nVERIFICAÇÃO DE PODERES, com oração pelo Rev. Vagner. E para constar eu, Reverendo César Veríssimo Marinho dos Reis, 2º Secretário, a tudo presente, digito, dato, e assino a presente ATA, a qual será transcrita pelo Secretário Executivo, Presb. Anízio Alves Borges, em livro próprio. São Paulo, 14/12/2.024.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-..-.-.-.-", "sessao_preparatoria": "ATA DA SESSÃO PREPARATÓRIA DA 35.aREUNIÃO ORDINÁRIA DO PRESBITÉRIO LESTE DE SÃO PAULO - PSSP . Aos catorze dias do mês de dezembro de 2024, (14/12/2024) às 9h12m, passa-se ao Exercício Devocional, lê-se o Salmo 100, canta-se os cânticos \" Grande é o Senhor \", \"Pra te Adorar \"e \"Em Espírito e em Verdade \". O Rev. Wellington ora suplicando a Deus pelo Pregador. É passada a palavra ao Licenciado Guilherme Oliveira da Silva, que faz a leitura bíblica em Gênesis 45:16 a 45, e em seguida oração; e segue com sua dissertação visando ser examinado para ordenação ao Sagrado Ministério conforme preceitua o CI/IPB, art. 120, alínea \"c\", e ainda sobre \"O Evangelho que Transforma Vidas\": a) Deus Cuida de Todas as Coisas; b) Deus Usa quem Ele Quer e Qualquer Coisa; c) Deus Provem Todas as Coisas Boas para o Seu Povo; e termina sua predica com uma oração; às 9h57m, encerra-se o Exercício Espiritual. E para constar eu, Reverendo César Veríssimo Marinho dos Reis, 2.o Secretário, a tudo presente, digito, dato e assino a presente ATA, a qual será transcrita pelo Secretário Executivo, Presbítero Anízio Alves Borges. São Paulo, 14/12/2024", "sessoes_regulares": ["ATA DA SESSÃO REGULAR ÙNICA DA 35.aREUNIÃO ORDINÁ RIA DO PRESBITÉRIO LESTE DE SÃO PAULO . Aos catorze dias do mês de dezembro de 2024, (14/12/2024) às 9h58m, sob a Presidência do Rev. Amauri Costa de Oliveira, e demais membros da Mesa: Rev. Amauri Costa de Oliveira, Presidente, Rev. Carlos Alberto Henrique, Vice-Presidente; Presb. Anízio Alves Borges, Secretário Executivo, Rev. Daniel Fogaça, 1º Secretário, Rev. César Veríssimo Marinho dos Reis; 2º Secretário; Valdir Soranso, Tesoureiro; e membros do Concílio supracitados. Ora o Rev. Atsushi e o Presidente a leitura do Termo de Convocação e do Horário Regimental. ELEIÇÃO DA COMISSÃO EXECUTIVA : Passa-se ao Processo de Eleição da nova Mesa que será a COMISSÃO EXECUTIVA - CE/PSSP para o período de 01/01/2025 a 31/12/2025. Registra-se a presença de 20 (vinte) membros votantes. Iniciado o pleito, é reeleito Presidente, em 1oescrutínio, o Rev. Amauri Costa de Oliveira; de igual forma, é reeleito Vice-Presidente, em 1oescrutínio, o Rev. Carlos Henrique; é reeleito 1º Secretário, em 1oescrutínio, o Rev. Daniel; é eleito 2º Secretário em 3oescrutínio, o Rev. Rogério de Castro Chaves; é eleito Tesoureiro, em 2oescrutínio, o Rev. Atsushi Miyajima. O Secretário Executivo terá o mandato de três anos, conforme o parágrafo 2odo art. 67 da CI/IPB. O Presidente, Rev. Amauri, convida o Rev. Laércio Máximo Rodrigues, para declarar empossados todos os eleitos. O Rev. Laércio, então, lê em 1º Coríntios 15:58 direcionando as atividades dos respectivos cargos para a glória de Deus e com oração audível declara solenemente empossados os eleitos. RECEPÇÃO DE DOCUMENTOS :Doc 01 , Termo de Convocação da 35ª RO/PSSP . Toma-se conhecimento e arquiva-se; Doc 02 , que trata de solicitação de ajuda ﬁnanceira do Rev. Jairo, toma-se conhecimento e encaminha a Comissão Campos e Finanças. Doc 03 , que trata do Relatório da Tesouraria do Presbitério, baixa a Comissão Permanente de Exame de Contas da Tesouraria. Doc. 04 , que trata do Certiﬁcado de Conclusão do Curso do Bel. Éfferson Soares Luz, toma-se conhecimento e arquiva-se. Doc. 05 , que trata da solicitação de Ordenação do Licenciado Guilherme Oliveira da Silva, toma-se conhecimento e dá-se prosseguimento aos passos constitucionais do Candidato. Doc. 06 , que trata da solicitação de transferência do Lic. Guilherme do Presbitério de Cascavel, toma-se conhecimento e dá-se prosseguimento ao processo de Ordenação. Doc. 07 , que trata do Relatório da Comissão de Tese do Bel. Ricardo Riul, toma-se conhecimento e aprova-se. Doc. 08 , que trata do encaminhamento do Aspirante ao Sagrado Ministério do Seminarista Rafael Sá, toma-se e baixa a Comissão de Exame de Candidatos. Doc. 09 , que trata do encaminhamento de Aspirante ao Sagrado Ministério Guilherme Francisco Rodrigues Paes Athu, toma-se conhecimento e baixa a Comissão de Exame de candidatos. Doc. 10 que trata da transferência do Aspirante ao Sagrado Ministério, Gabriel Bastos Ricci Justino, toma-se conhecimento e baixa a Comissão de Exame de Candidatos. Passa-se ao exame do Sermão de Prova do Candidato Guilherme Francisco Rodrigues Paes Athu, pelo plenário. Conduzido pelo Presidente, o exame, perguntas e inquirições resultaram proveitoso e o Candidato ao Sagrado Ministério foi aprovado por unanimidade. Dada a palavra ao Rev. Wellington Aparecido Costa Baldez, que passa a agradecer a Deus pela vida do PSSP - Presbitério Leste de São Paulo e compartilha de suas aspirações no Ministério Pastoral na Bolívia para onde foi convidado a trabalhar. Ora pelo Rev. Wellington o Rev. Gustavo. Registra-se voto a apreciação pela vida do Rev. Wellington por todo o tempo de Ministério que o Senhor concedeu a todo este Presbitério na caminhada conjunta. RECEPÇÃO DE DOCUMENTOS: (continuação) Doc. 11 , que trata do Pré-Projeto de Plantação de Igreja, Jardim Primavera-Itaquaquecetuba, toma-se conhecimento e baixa-se a Comissão de\n\nFinanças. Doc. 12 , Pré-Projeto de Plantação de Igreja, Vila Rosária, toma-se conhecimento e baixa-se a Comissão de Finanças. Passa-se a palavra ao Rev. Fábio Luiz de Carvalho para que se apresente perante o Presbitério, visando sua recepção no PSSP , para atuar como Pastor Auxiliar da Igreja Presbiteriana da Penha; A transferência do referido Ministro procedente do Presbitério Metropolitano de São Paulo, se dará conforme preceitua o art. 88, alínea \"c\", e art. 4 da CI/IPB, cujo Ofício de 06/12/2024 já foi recepcionado pelo Secretário Executivo do PSSP; o referido obreiro faz um breve resumo de sua vida e Ministério. O PSSP dispensa o referido obreiro do Exame de Recepção neste Presbitério. DOC. I , oriundo da Comissão de Exame de Candidatos: Quanto ao Doc. 04 acerca do Bel. Éfferson Soares Luz: O PSSP observa que o Bel. concluiu o Curso de Teologia no JMC e no momento encontra-se em conversação com a IP de Içara, no Estado de Santa Catarina. Assim, o PSSP resolve : Aguardar a Recepção do Documento solicitado ou não a transferência do obreiro; DOC. II, -Quanto ao Doc. 6, acerca do Bel. Guilherme, o PSSP observa que, uma vez que cumpriu os passos constitucionais, o PSSP resolve : encaminhá-lo para exame no plenário e, aprovado no exame, proceda-se sua ordenação ao Sagrado Ministério; DOC. III , Quanto ao Doc. 07 acerca do Bel. Ricardo Riul: O PSSP resolve : Proceder o Exame de Candidato e, uma vez aprovado, que seja ordenado ao Sagrado Ministério; DOC. IV, Quanto aos Docs. 8 e 9 acerca dos Ir. Rafael Garcia de Sá e Ir. Guilherme Francisco Rodrigues Paes Athu, respectivamente: O PSSP resolve : aprová-los para o envio dos candidatos, aos respectivos Seminários JMC e SPS em Campinas. Passa-se ao exame do Lic. Guilherme que após inquirições do plenário é aprovado por unanimidade e o PSSP resolve ainda , concede-se poderes a CE/PSSP para proceder a transferência do referido obreiro. Passa-se ao exame do Bel. Ricardo Riul. O mesmo é inquirido e aprovado por unanimidade e ora pelo Bacharel o Rev. Atsushi, suplicando as bênçãos de Deus sobre o mesmo. O PSSP resolve deﬁnir o Culto de Ordenação para o dia 05 de janeiro de 2025, as 9h30m na IP Penha; e nomear a seguinte Comissão de Ordenação: Rev. Amauri (Relator), Rev. César, Rev. Daniel, Rev. Jairo, Rev. Filipe, Presb. Francisco Lima, Presb. Laércio Ferreira Lima. DOC. V , oriundo da Comissão Exame de Contas da Tesouraria do Presbitério; A Comissão apresenta ao Plenário, um plano de custos para o Presbitério. O PSSP resolve : aprovar em seus termos. DOC. VI , oriundo da Comissão de Legislação e Justiça; Quanto aos Docs. 05 e 06 que versam sobre a ordenação e transferência do Lic. Guilherme Oliveira da Silva; tendo em vista que o Licenciado já foi examinado em seu Sermão de Prova alcançando unanimidade em sua aprovação, inquirido pelo Concílio e também aprovado. O PSSP resolve :a) Deﬁnir o Culto de Ordenação do referido Candidato para o dia 21 de dezembro as 20 horas na IP Jd. Popular. b) Nomear a seguinte Comissão de Ordenação: Rev. Laércio (Relator), Rev. Maycon, Rev. Daniel, Rev. Rogério, Presb. Nichimura, Presb. Cleber. c)Conceder poderes à Comissão Executiva do PSSP CE/PSSP , para proceder a transferência do referido obreiro. DOC. VII ; quanto ao Doc. 10 que trata acerca da transferência do Candidato ao Sagrado Ministério, Sem. Gabriel Bastos Ricci Justino, o PSSP resolve : aprovar a solicitação do seu tutor Eclesiástico. DOC. VIII; quanto ao Doc. 13, que trata do Relatório da Comissão Especial de Plantação e Revitalização de Igreja (Jd. Primavera), O PSSP resolve :a)aprovar o pré-projeto da Congregação do Jardim Primavera nos seguintes termos; b)os Relatórios deverão ser entregues a cada dois meses, acompanhado do planejamento proposto no Projeto; c)deverá ser apresentado o Relatório Financeiro a cada dois meses conforme proposto\n\nem Projeto orçado, realizado e seus comprovantes; d)aprovar o montante de R$ 24.000 reais para o ano de 2025. DOC. IX; quanto ao Doc. 14, que trata Do Relatório da Comissão Especial de Plantação e Revitalização de Igreja (Jd. Vl. Rosária), o PSSP resolve :a)aprovar o Projeto nos seguintes termos; b)os Relatórios deverão ser entregues a cada dois meses, acompanhado do planejamento proposto no Projeto; c)deverá ser apresentado o Relatório Financeiro a cada dois meses conforme proposto em Projeto orçado, realizado e seus comprovantes; d)aprovar o montante de R$ 36.000 reais para o ano de 2025, ou seja R$ 3.000 mil reis por mês. Quanto à reeleição do Reverendo Amauri Costa de Oliveira, para novo período de 05 anos no pastorado da IP da Penha, o PSSP resolve encaminhar ao Conselho da aludida Igreja, o seguinte Termo de Posse para ser lido perante a Assembleia Geral: \"O PRESBITÉRIO LESTE DE SÃO PAULO - PSSP , em sua 35ª Reunião Ordinária realizada no dia 14/12/2024 na CONGREGAÇÃO PRESBITERIANA DE ANÁLIA FRANCO, em São Paulo, Capital, deliberou por aprovar a Eleição Pastoral da IGREJA PRESBITERIANA DA PENHA, realizada em sua Sede, Rua Major Rudge no145, Penha, São Paulo, Capital, no dia 29/09/2024, conforme a previsão contida no Capítulo III, Art. 4º, § 2º; Artigos 6oe 7ode seu Estatuto Social e Artigos 30 a 34 e demais aplicáveis da CI/IPB, tudo lavrado na Ata no190 de sua Assembleia Geral Extraordinária, na qual foi reeleito o Reverendo AMAURÍ COSTA DE OLIVEIRA, como Pastor Efetivo em tempo integral. Dessa forma, com fundamento na alínea ado artigo 34 da CI/IPB, o PRESBITÉRIO LESTE DE SÃO PAULO - PSSP , no exercício de sua competência Constitucional, declara solenemente, para os devidos ﬁns de direito, EMPOSSADO o Reverendo AMAURI COSTA DE OLIVEIRA, como Pastor Efetivo e representante legal da IGREJA PRESBITERIANA DA PENHA para o período de 01/01/2025 a 31/12/2029. Por ser a expressão da verdade, ﬁrmamos o presente TERMO DE POSSE. São Paulo, 12 de janeiro de 2025. Sala das Sessões, Presbítero Anízio Alves Borges, Secretário Executivo do PSSP .\"O PSSP resolve registrar um voto de Gratidão a Congregação Presbiteriana Anália Franco, pela recepção calorosa dada ao Presbitério. Resolve ainda convocar o PSSP para reunir-se ordinariamente nos dias 31 de janeiro e 01 de fevereiro de 2025, com início às 20 horas do dia 31, na IP Penha. O Sr. Presidente apresenta o Missionário locado em Salamanca, na Espanha, Rev. Gladston Lucas Oliveira e encerra-se a reunião com oração pelo Presb. Nichimura as 15h12m. Eu, Rev. Rogério de Castro Chaves, 2.oSecretário, a tudo presente, digito, dato e assino a presente ata, a qual será transcrita pelo Secretário Executivo, Presb. Anízio Alves Borges. São Paulo, 14 de dezembro de 2024 . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 