  VALUES ('36ª RO', '2025-01-31', '2025-01-31', 'ordinaria', 'realizada')
  ON CONFLICT (numero) DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NULL THEN SELECT id INTO v_id FROM reunioes WHERE numero = '36ª RO'; END IF;

