  END IF;
  RAISE NOTICE '36ª RO - 1ª RE - 2025 importada';


  -- 36ª RO - 2ª RE - 2025 (2025-06-06)
  INSERT INTO reunioes (numero, data_inicio, data_fim, tipo, status)
  VALUES ('36ª RO - 2ª RE - 2025', '2025-06-06', '2025-06-06', 'extraordinaria', 'realizada')
  ON CONFLICT (numero) DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NULL THEN SELECT id INTO v_id FROM reunioes WHERE numero = '36ª RO - 2ª RE - 2025'; END IF;

  SELECT id INTO v_ata FROM atas WHERE reuniao_id = v_id;
  IF v_ata IS NULL THEN
    INSERT INTO atas (reuniao_id, status, conteudo) VALUES (v_id, 'publicada', '{"verificacao_poderes": "ATA DO ATO DE VERIFICAÇÃO DE PODERES DA 2ª REUNIÃO EXTRAORDINÁRIA DA 36ª REUNIÃO ORDINÁRIA DO PRESBITÉRIO LESTE DE SÃO PAULO - PSSP Às 19h50m, do dia seis de junho de dois mil e vinte e cinco (06/06/2025), na Igreja Presbiteriana da Penha, situada na Rua Major Rudge, 145 - Penha, São Paulo - Capital, reúne-se, previamente convocado, o Presbitério Leste de São Paulo - PSSP . Composição da Mesa: Reverendo Amauri Costa de Oliveira, Presidente; Presbítero Anízio Alves Borges, Secretário Executivo; Reverendo Daniel Fogaça, 1º Secretário; Reverendo Rogério de Castro Chaves, 2º Secretário; e Reverendo Atsushi Miyajima, Tesoureiro. Feita a chamada pelo Secretário Executivo, registram-se a presença dos seguintes ministros: Rev. Adriano Pedrosa Ferreira, Rev. Amauri Costa de Oliveira, Rev. Atsushi Miyajima, Rev. César Veríssimo Marinho dos Reis, Rev. Cornélio Caldeira de Castro, Rev. Daniel Fogaça, Rev. Filipe Gomes Checon Pereira, Rev. Fábio Carvalho, Rev. Gustavo Alex Faria Custódio, Rev. Jairo Isac Rodrigues, Rev. Maycon Rodrigues, Rev. Ricardo Riul e Rev. Rogério de Castro Chaves. Todos os presentes assinaram o Livro de Presença do Concílio. Ausentaram-se os seguintes ministros: Rev. Carlos Eduardo Corrêa Lima, Rev. Carlos Roberto Spiaze, Rev. Carlos Alberto Henrique, Rev. Israel Scalioni, Rev. Jean Francesco Afonso Lima Gomes, Rev. Juliano Caetano Socio, Rev. Laércio Máximo Rodrigues, Rev. Michael Fassheber, Rev. Vagner de Jesus Queirós, Rev. Wellington Aparecido Costa Baldez, em serviço missionário na Bolívia, e Rev. Jessé Silveira Fogaça, em campo missionário no Timor Leste - Ásia. Registram-se a presença das seguintes igrejas , por meio de seus representantes: Igreja Presbiteriana da Penha, representada pelo Presb. Anízio Alves Borges; e Igreja Presbiteriana de Vila Buenos Aires, representada pelo Presb. Idenal Nichimura. Ausentes os representantes das Igrejas: IP do Jardim Castelo, IP Jardim Popular, IP Vila Esperança e IP Vila Laís. Havendo quórum, 20h00m, o Presidente, Rev. Amauri Costa de Oliveira, declara instalada a 2ª Reunião Extraordinária da 36ª Reunião Ordinária do Presbitério Leste de São Paulo - PSSP . Às 20h00m, encerra-se a sessão de veriﬁcação de poderes com oração feita pelo Rev. Maycon Rodrigues. E para constar eu, Reverendo Rogério de Castro Chaves, 2º Secretário, a tudo presente, digito, dato, e assino a presente ATA, a qual será transcrita pelo Secretário Executivo, Presbítero Anízio Alves Borges, em livro próprio.São Paulo, 06 de junho de 2025.", "sessao_preparatoria": "ATA DA SESSÃO PREPARATÓRIA DA 2ª REUNIÃO EXTRAORDINÁRIA DA 36ª REUNIÃO ORDINÁRIA DO PRESBITÉRIO LESTE DE SÃO PAULO - PSSP Aos seis dias do mês de junho de dois mil e vinte e cinco (06/06/2025), às 20h20m, passa-se ao exercício devocional. Entoam-se os cânticos \"Grande é o Senhor\"e \"Cantai ao Senhor\", conduzidos pelo Reverendo Fábio Carvalho. Em seguida, o Rev. Gustavo Custódio ora ao Senhor, agradecendo pelo sucesso da cirurgia da irmã Kênia, esposa do Rev. Jairo Isac Rodrigues, e intercedendo pela reunião. Passa-se a palavra ao candidato Ali Mohammed Rahim , que faz a leitura do texto bíblico de Isaías 6.8, ora, e prossegue com a exposição devocional, como parte de seu exame para ordenação ao Sagrado Ministério, conforme preceitua o art. 120, alínea \"c\", da Constituição da Igreja Presbiteriana do Brasil. O candidato apresenta como tema da exposição: \"Enviame a mim\", fundamentando sua mensagem nos seguintes argumentos: 1) Deus nos chamou; 2) Devemos estar preparados; e 3) Devemos contar com o suporte uns dos outros.Às 20h45m, encerra-se o exercício devocional com oração feita pelo Reverendo Gian. E, para constar, eu, Rev. Rogério de Castro Chaves, 2º Secretário, presente a tudo, redijo, datilho e assino a presente ata, a qual será transcrita pelo Secretário Executivo, Presbítero Anízio Alves Borges. São Paulo,\n\n06 de junho de 2025.", "sessoes_regulares": ["ATA DA SESSÃO REGULAR ÚNICA DA 2ª REUNIÃO EXTRAORDINÁRIA DA 36ª REUNIÃO ORDINÁRIA DO PRESBITÉRIO LESTE DE SÃO PAULO - PSSP Às 20h46m, sob a presidência do Rev. Amauri Costa de Oliveira, inicia-se a sessão regular única da 2ª Reunião Extraordinária da 36ª RO do PSSP . O Rev. Adriano Pedrosa ora ao Senhor, suplicando a direção de Deus. Registra-se a presença do Rev. Gian, atuando como tradutor oﬁcial do candidato Ali Mohammed Rahim e do Rev. Maurício Nepomucemo, como convidado. Doc. 01, Termo de Convocação. Toma-se conhecimento e arquiva-se. Doc. 02 , Relatório da Comissão de Ordenação do candidato Ali Mohammed Rahim. Lido pelo Rev. Daniel Fogaça. O Rev. César Veríssimo Marinho dos Reis solicita esclarecimentos sobre o trecho do relatório que informa que o candidato já fora ordenado. O Rev. Gian, como companheiro de ministério, esclarece que o candidato foi anteriormente ordenado na Igreja do Curdistão, sendo agora submetido ao processo de ordenação do Presbitério Leste de São Paulo em conformidade com os preceitos da Constituição da Igreja Presbiteriana do Brasil, especialmente o artigo 120, que trata dos requisitos e exames para a ordenação ao Sagrado Ministério, e o artigo 27, que aﬁrma a autoridade exclusiva dos presbitérios para ordenar ministros. Após discussão, avaliação e parecer favorável da Comissão, o PSSP resolve aprovar a ordenação do candidato Ali Mohammed Rahim . O Rev. Cornélio Caldeira de Castro ora em gratidão a Deus pelo avanço da obra missionária da IPB, destacando a contribuição da Agência Presbiteriana de Missões Transculturais - APMT. O PSSP marca o Culto de Ordenação para o dia 08 de junho de dois mil e vinte e cinco, às 18h00, na Igreja Presbiteriana da Penha, situada na Rua Major Rudge, 145 - Penha, São Paulo - Capital, e nomeia a seguinte Comissão de Ordenação: Rev. César Veríssimo Marinho dos Reis, Rev. Carlos Alberto Henrique, Rev. Fábio Carvalho e Presb. Idenal Nichimura. Doc. 03 , Solicitação de apoio do Rev. Gustavo Custódio. O Rev. Gustavo leu pessoalmente o documento, manifestando gratidão ao PSSP e solicitando apoio ﬁnanceiro no valor de R$ 2.500,00 mensais, pelo período de doze meses. O Rev. César Marinho solicitou esclarecimentos quanto ao propósito do recurso, e o Rev. Daniel Fogaça questionou a mudança de campo missionário. O Rev. Gustavo explicou que, após experiências missionárias na Albânia e posteriormente no Kosovo, retornou ao Brasil em virtude de restrições locais, passando a orar pela possibilidade de atuação missionária na Grécia. O Rev. Daniel enfatizou a importância de a igreja considerar também o interior do Brasil, onde ainda há cidades sem presença da IPB. O Rev. César questionou ao tesoureiro, Rev. Atsushi Miyajima, sobre a possibilidade orçamentária para atender ao pedido. O mesmo informou o saldo disponível em caixa.Após exposição e deliberação, o PSSP resolve aprovar um pagamento único de R$ 10.000,00 (dez mil reais), como oferta de apoio ao projeto missionário do Rev. Gustavo Custódio. Doc. 04 , Relatório de Ordenação ao Sagrado Ministério do Bel. Ayrton da Silva Moreira Gomes. Lido pelo Rev. César Veríssimo Marinho dos Reis, relator. O relatório tem por objetivo apresentar como se deu a alvissareira Ordenação do referido candidato, registrando os atos litúrgicos, a participação da Comissão e a condução do culto solene de ordenação, realizado sob a chancela deste Presbitério. Após leitura e manifestação dos membros do concílio, o PSSP resolve aprovar o referido relatório, registrando louvor a Deus pela vida e vocação do novo ministro da Palavra.Encerra-se a reunião às 21h30m, com a oração do convidado, Reverendo Maurício Nepomuceno, que ora agradecendo ao Senhor pela condução dos trabalhos, pelo envio de missionários transculturais e pela unidade do Presbitério.E para constar eu, Rev. Rogério de Castro Chaves, 2º Secretário, a\n\ntudo presente, digito, dato e assino a presente ata, a qual será transcrita pelo Secretário Executivo, Presb. Anízio Alves Borges, em livro próprio. São Paulo, 06 de junho de 2025. . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .